/* callout autohide  
from https://github.com/Scaryharry4*/
.callout:not(.is-collapsible) {
  display: flex;
  flex-direction: column;
  transition: 500ms;
  opacity: 1;
  flex-grow: 1;
}

.callout:not(.is-collapsible):hover {
  opacity: 1;
}

.callout:not(.is-collapsible) .callout-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 500ms ease;
  flex-grow: 0;
}

.callout:not(.is-collapsible):hover .callout-content {
  max-height: 1000px;
  flex-grow: 1;
}

.callout-content .callout {
  opacity: 1;
}

