body {
  --inline-code-padding-vertical: 0.1em;
  --inline-code-padding-horizontal: 0.2em;
}

/* 阅读模式 */
.view-content .markdown-reading-view .markdown-preview-sizer div:not(.el-pre) code {
  color: var(--inline-code-color) !important;
  background-color: var(--color-base-20);
}

/* 实时预览 */
.codeblock-customizer.codeblock-customizer-style-inline-code .markdown-rendered :not(pre) > code.codeblock-customizer-inline-code {
  color: var(--inline-code-color) !important;
  background-color: var(--color-base-20);
}

/* 源码模式 */
.cm-s-obsidian span.cm-inline-code:not(.cm-formatting):not(.cm-hmd-indented-code):not(.obsidian-search-match-highlight),
.cm-formatting.cm-formatting-code.cm-inline-code {
  color: var(--inline-code-color);
  background-color: var(--color-base-20);
}

/*────────── Core Plugin: File Explorer ──────────*/
.nav-files-container {
  padding-top: var(--size-2-1);
}

.nav-file-title {
  transition: padding, transform var(--anim-duration-fast) var(--anim-motion-smooth);
}
.nav-file-title:active {
  transform: translateY(2px);
}

.nav-file-tag {
  color: var(--nav-file-tag-color);
  background: var(--nav-file-tag-bg);
  margin-top: 1px;
}
.nav-file-title.is-active .nav-file-tag {
  margin-top: 0px;
}

/*────────── SS: Colored File Explorer Folders ──────────*/
body {
  --nav-folder-color: var(--nav-item-color);
  --nav-folder-bg-color: transparent;
  --nav-folder-bg-color-hover: var(--nav-item-background-hover);
  --nav-folder-collapse-color: var(--nav-collapse-icon-color);
}

body:not(.colorful-folders-length) .nav-folder-children > .nav-folder .nav-folder-title,
body:not(.colorful-folders-length) .nav-files-container > div > .nav-folder .nav-folder-title {
  color: var(--nav-folder-color);
  background: var(--nav-folder-bg-color);
  border-radius: 6px;
}
body:not(.colorful-folders-length) .nav-folder-children > .nav-folder .nav-folder-title:hover,
body:not(.colorful-folders-length) .nav-files-container > div > .nav-folder .nav-folder-title:hover {
  color: var(--nav-folder-color);
  background: var(--nav-folder-bg-color-hover);
}

.nav-folder .tree-item-icon svg.svg-icon {
  color: var(--nav-folder-collapse-color);
}

body.colorful-folders_collapse-indicator .nav-folder-children > .nav-folder:nth-child(8n+2),
body.colorful-folders_collapse-indicator .nav-files-container > div > .nav-folder:nth-child(8n+2) {
