    var(--file-line-width) - var(--wide-code-left-ev-adj)
  );
}

body:has(.cm-gutters) {
  --wide-code-left-ev-adj: 1.7rem;
  --wide-code-min-left-ev: 6.5rem;
}

@container content-view (width > 50px) {
  /* 阅读模式 - 适配你提供的HTML结构 */
  :is(.wide-codeblock-global, .wide-codeblock) .markdown-preview-sizer > div.el-pre {
    width: 100cqi;
    margin-left: calc(max(100cqi - var(--file-line-width), 1rem) / 2 * -1) !important;
  }
  /* 确保pre元素也跟随变宽 */
  :is(.wide-codeblock-global, .wide-codeblock) .el-pre pre {
    width: 100% !important;
  }
